#include <stdbool.h>
#include <stddef.h>
#include <string.h>

void apply(int *values, size_t count, int (*f)(int))
{
    for (size_t i = 0; i < count; i++) values[i] = f(values[i]);
}

size_t count_if(const int *values, size_t count, bool (*test)(int))
{
    size_t n = 0;
    for (size_t i = 0; i < count; i++) {
        if (test(values[i])) n++;
    }
    return n;
}

int negate(int x)
{
    return -x;
}

bool is_negative(int x)
{
    return x < 0;
}

int compare_ints(const void *a, const void *b)
{
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int compare_by_length(const void *a, const void *b)
{
    const char *x = *(const char *const *)a;
    const char *y = *(const char *const *)b;
    size_t lx = strlen(x), ly = strlen(y);
    if (lx != ly) return lx < ly ? -1 : 1;
    return strcmp(x, y);
}

unitTests:
TEST("applying a function") { int v[] = {1, -2, 3}; apply(v, 3, negate); CHECK_EQ(v[0], -1); CHECK_EQ(v[1], 2); CHECK_EQ(v[2], -3); apply(v, 0, negate); CHECK_EQ(v[0], -1); }
TEST("counting with a test") { int v[] = {-5, 3, -1, 0, -7}; CHECK_EQ(count_if(v, 5, is_negative), (size_t)3); CHECK_EQ(count_if(v, 0, is_negative), (size_t)0); }
TEST("sorting numbers") { int v[] = {5, -3, 2147483647, 0, -2147483647 - 1, 5}; qsort(v, 6, sizeof v[0], compare_ints); CHECK_EQ(v[0], -2147483647 - 1); CHECK_EQ(v[1], -3); CHECK_EQ(v[2], 0); CHECK_EQ(v[3], 5); CHECK_EQ(v[4], 5); CHECK_EQ(v[5], 2147483647); }
TEST("sorting words by length") { const char *w[] = {"pear", "fig", "banana", "kiwi", "apple", "date"}; qsort(w, 6, sizeof w[0], compare_by_length); CHECK_STR(w[0], "fig"); CHECK_STR(w[1], "date"); CHECK_STR(w[2], "kiwi"); CHECK_STR(w[3], "pear"); CHECK_STR(w[4], "apple"); CHECK_STR(w[5], "banana"); }

